code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y, x))
            boxes = {}
            for color, pts in colors.items():
                ys = [p[0] for p in pts]
                xs = [p[1] for p in pts]
                boxes[color] = (max(ys)-min(ys)+1) * (max(xs)-min(xs)+1)
            order = sorted(colors, key=lambda color: (-boxes[color], color))
            mapping = {color: order[-1-i] for i, color in enumerate(order)}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
'''
